def solution(answers):
    patterns = [[1, 2, 3, 4, 5], [2, 1, 2, 3, 2, 4, 2, 5], [3, 3, 1, 1, 2, 2, 4, 4, 5, 5]]
    scores = [0, 0, 0]

    def check_score(index, scores):
        if index >= len(answers):
            return scores
        for i in range(3):
            if answers[index] == patterns[i][index % len(patterns[i])]:
                scores[i] += 1
        return check_score(index + 1, scores)

    scores = check_score(0, scores)
    max_score = max(scores)
    return [i + 1 for i in range(3) if scores[i] == max_score]

def solution(numbers, target):
    cnt=0
    queue=deque([[numbers[0],0],[-numbers[0],0]])
    idx=0
    while queue:
        pop,idx=queue.popleft()
        idx+=1
        if idx<len(numbers):
            queue.append([pop+numbers[idx],idx])
            queue.append([pop-numbers[idx],idx])
        else:
            if pop==target: cnt+=1
    return cnt

def solution(maps):
    from collections import deque

    def bfs(start, target):
        queue = deque([start])
        visited = [[False] * len(maps[0]) for _ in range(len(maps))]
        visited[start[0]][start[1]] = True
        distance = 0

        while queue:
            for _ in range(len(queue)):
                x, y = queue.popleft()
                if (x, y) == target:
                    return distance
                for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < len(maps) and 0 <= ny < len(maps[0]) and not visited[nx][ny] and maps[nx][ny] != 'X':
                        visited[nx][ny] = True
                        queue.append((nx, ny))
            distance += 1
        return -1

    start = end = lever = None
    for i in range(len(maps)):
        for j in range(len(maps[0])):
            if maps[i][j] == 'S':
                start = (i, j)
            elif maps[i][j] == 'E':
                end = (i, j)
            elif maps[i][j] == 'L':
                lever = (i, j)

    distance_to_lever = bfs(start, lever)
    if distance_to_lever == -1:
        return -1
    distance_to_exit = bfs(lever, end)
    if distance_to_exit == -1:
        return -1
    return distance_to_lever + distance_to_exit

def solution(board):
    def count_marks(board):
        x_count = sum(row.count("X") for row in board)
        o_count = sum(row.count("O") for row in board)
        return x_count, o_count

    def check_winner(board, mark):
        return any(all(cell == mark for cell in row) for row in board) or \
               any(all(board[i][j] == mark for i in range(3)) for j in range(3)) or \
               all(board[i][i] == mark for i in range(3)) or \
               all(board[i][2 - i] == mark for i in range(3))

    x_count, o_count = count_marks(board)
    if o_count > x_count or x_count > o_count + 1:
        return False
    if check_winner(board, "X") and x_count != o_count + 1:
        return False
    if check_winner(board, "O") and x_count != o_count:
        return False
    return True

