def merge(left, right):
    sorted_list = []
    while left and right:
        if left[0][1] > right[0][1] or (left[0][1] == right[0][1] and left[0][0] < right[0][0]):
            sorted_list.append(left.pop(0))
        else:
            sorted_list.append(right.pop(0))
    sorted_list.extend(left or right)
    return sorted_list

