def solution(id_list, report, k):
    from collections import defaultdict

    report_count = defaultdict(set)
    user_reported = set(report)

    for r in user_reported:
        reporter, reported = r.split()
        report_count[reported].add(reporter)

    result = [0] * len(id_list)
    for i, user in enumerate(id_list):
        if len(report_count[user]) >= k:
            for reporter in report_count[user]:
                result[id_list.index(reporter)] += 1

    return result

