def solution(number, k):
    def helper(s, k):
        if k == 0 or not s:
            return s
        if len(s) == k:
            return ''
        for i in range(len(s) - 1):
            if s[i] < s[i + 1]:
                return helper(s[:i] + s[i + 1:], k - 1)
        return s[:-1] + helper(s[-1:], k - 1)

    return helper(number, k)

