def solution(arr):
    def compress(x, y, size):
        if size == 1:
            return (1, 0) if arr[x][y] == 1 else (0, 1)

        half = size // 2
        count1 = compress(x, y, half)
        count2 = compress(x, y + half, half)
        count3 = compress(x + half, y, half)
        count4 = compress(x + half, y + half, half)

        total_ones = count1[0] + count2[0] + count3[0] + count4[0]
        total_zeros = count1[1] + count2[1] + count3[1] + count4[1]

        if total_ones == 0:
            return (0, 1)
        if total_zeros == 0:
            return (1, 0)

        return (total_ones, total_zeros)

    return list(compress(0, 0, len(arr)))

