def solution(grid):
    def dfs(x, y, direction, visited, cycles):
        if (x, y, direction) in visited:
            cycles.append((x, y, direction))
            return True
        visited.add((x, y, direction))
        nx, ny = (x + dx[direction]) % len(grid), (y + dy[direction]) % len(grid[0])
        if grid[nx][ny] == 'L':
            direction = (direction - 1) % 4
        elif grid[nx][ny] == 'R':
            direction = (direction + 1) % 4
        return dfs(nx, ny, direction, visited, cycles)

    dx = [0, 1, 0, -1]
    dy = [1, 0, -1, 0]
    visited = set()
    cycles = []

    for i in range(len(grid)):
        for j in range(len(grid[0])):
            for d in range(4):
                if (i, j, d) not in visited:
                    dfs(i, j, d, visited, cycles)

    return cycles

