def solution(s):
    def recursive_split(index, count_x, count_y):
        if index == len(s):
            return 1 if count_x == count_y else 0
        if s[index] == 'x':
            count_x += 1
        elif s[index] == 'y':
            count_y += 1
        if count_x == count_y:
            return 1 + recursive_split(index + 1, 0, 0)
        return recursive_split(index + 1, count_x, count_y)

    return recursive_split(0, 0, 0)
